// === Tab: mySketch ===
// By Roni Kaufman

let myShader;
let ditherImg;

function preload() {
  myShader = createShader(vert, frag);
	ditherImg = loadImage("https://openprocessing.org/sketch/1152071/files/dither.png")
}

function setup() {
	let size = max(windowWidth, windowHeight);
	createCanvas(size, size, WEBGL);
	noStroke();
}

function draw() {
	shader(myShader);
	myShader.setUniform('u_res', [width, height]);
	myShader.setUniform('u_time', millis()/1000);
	myShader.setUniform('u_dither', ditherImg);

	rect(0,0,width,height);
}

// === Tab: vert ===
const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;
			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
			gl_Position = positionVec4;
		}
`;

// === Tab: frag ===
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_res;
//uniform vec2 u_mouse;
uniform sampler2D u_dither;
uniform float u_time;

float grid(float inp) {
	if(inp*16.0 + texture2D(u_dither, vec2(mod(gl_FragCoord.x,4.0)/4.0, mod(gl_FragCoord.y,4.0)/4.0))[0]*15.0+0.5 > 16.0) {
		return 1.0;
	}
	return 0.0;
}

float sinFractionalOffset(float offs) {
	return sin((u_time+gl_FragCoord.x/100.0+gl_FragCoord.y/(33.3*(sin(u_time)+2.0)))+2.094395*offs)*0.5+0.5;
}

void main() {
	gl_FragColor = vec4(
		grid(sinFractionalOffset(0.0)),
		grid(sinFractionalOffset(1.0)),
		grid(sinFractionalOffset(2.0)),
		1.0);
}
`;

